import numpy as np
np.random.seed(42)  # Fixed seed for reproducibility


def kissing_number11() -> np.ndarray:
    """
    Constructs a collection of 11-dimensional points with integral coordinates such that their maximum norm is smaller than their minimum pairwise distance, aiming to maximize the number of points.

    Returns:
        points: np.ndarray of shape (num_points,11)
    """
    d = 11
    # Generate lattice shell points
    r = 5  # Initial shell radius
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            for z in range(-r, r + 1):
                # Generate points satisfying ||p|| <= r
                point = np.array([x, y, z] + [0] * (d - 3), dtype=np.int64)
                if np.linalg.norm(point) <= r:
                    points.append(point)
    points = np.array(points)

    # Filter points to ensure constraints are satisfied
    filtered_points = []
    for i, p_i in enumerate(points):
        valid = True
        for j, p_j in enumerate(points):
            if i != j:
                if np.linalg.norm(p_i) > np.linalg.norm(p_j - p_i):
                    valid = False
                    break
        if valid:
            filtered_points.append(p_i)
    return np.array(filtered_points)


